import {explorationExample} from './career-exploration-ui.js';
import {coreWorkBank} from './core-work.js';
import {careerComparisonOptions} from './career-comparisons.js';
import {careerCheckSpec,careerCheckComplete} from './career-check-questions.js';
import {careerCheckReadiness} from './career-check-readiness.js';
import {directMatchCandidates} from './direct-match-candidates.js';
import {planMatchCandidates} from './plan-matches.js';
import {careerTitle,careerEducationSummary} from './career-presentation.js';
import {occupationById} from './occupation-data.js';
import {formatSalary,salaryProgression} from './salary-progression.js';
import {studyCostSummary} from './study-cost-summary.js';
import {escapeHTML as h} from './html.js';
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const url=(id,index=0)=>id.startsWith('degree-')?'#/journey/degree-check/'+encodeURIComponent(id):'#/journey/check-career/'+encodeURIComponent(id)+'/'+index;
function routeTable(rows){
 if(!rows.length)return '';
 return '<details class="more-info"><summary>Compare training, starting pay and monthly room</summary><p>Examples use the guide’s existing cost and pay references. School costs can include living expenses; the breakdown below shows what is included. These are different routes to explore.</p><div class="comparison-table-scroll" tabindex="0" role="region" aria-label="Profession route comparison"><table class="profession-route-table"><thead><tr><th scope="col">Profession</th><th scope="col">Training example</th><th scope="col">Cost before aid</th><th scope="col">First paid stage</th><th scope="col">Monthly room</th></tr></thead><tbody>'+rows.map(r=>{const c=studyCostSummary(r.id);return '<tr><th scope="row">'+h(careerTitle(r.o))+'</th><td>'+(c?h(c.duration)+'<small>'+h(c.example)+'</small>':'Review the profession’s training route')+'</td><td>'+(c?money(c.cost)+'<small>'+c.rows.map(x=>h(x.label)+': '+money(x.amount)).join('<br>')+'</small>':'No cost reference available')+'</td><td>'+formatSalary(r.firstPay)+' / year<small>'+h(salaryProgression(r.id)?.paidTraining?.label||'Entry level after required training')+(r.requiresExperience?' · prior related experience required':'')+'</small></td><td>'+(Number.isFinite(r.monthlyRemaining)?money(Math.abs(r.monthlyRemaining))+(r.monthlyRemaining<0?' shortfall':' remaining'):'Set a lifestyle budget first')+'</td></tr>';}).join('')+'</tbody></table></div><p>Monthly room uses your lifestyle expenses, savings and entered loan payments. Unfunded education costs are separate. Pay and costs are references, not offers.</p></details>';
}
export function careerComparisonsPanel(s){
 const {rows,reviewed}=careerComparisonOptions(s);if(!rows.length&&!reviewed.length)return '';
 const card=r=>{const why=careerCheckReadiness(s,r.id,{includeRanking:false});return '<article class="career-comparison-card"><h3>'+h(careerTitle(r.o))+'</h3><p>'+h(r.reason)+'</p><p>'+h(careerEducationSummary(r.o))+'</p><p><strong>'+formatSalary(r.firstPay)+' / year</strong> · '+h(salaryProgression(r.id)?.paidTraining?.label||'starting-pay reference')+'</p>'+(r.requiresExperience?'<p>Related work experience usually comes before this role.</p>':'')+'<p class="match-note"><strong>'+h(why.headline)+'.</strong> '+h(why.detail)+'</p><a class="button secondary" href="'+url(r.id,why.nextIndex)+'">'+(r.started?'Continue comparison':'Compare the work')+' · '+r.questionCount+' questions →</a></article>';};
 return '<section class="career-comparisons" id="career-comparisons"><h2>Explore a wider range of professions</h2><p>Before settling on your first matches, compare another kind of work. These professions connect with your interests and could offer another education or income route. The questions help establish whether the daily work fits; higher pay alone does not make a match.</p><p><a href="#first-matches" data-scroll-to="first-matches">See my current matches ↓</a></p><div class="career-comparison-grid">'+rows.slice(0,3).map(card).join('')+'</div>'+routeTable(rows.slice(0,3))+(rows.length>3?'<details class="more-info"><summary>More professions to compare</summary><div class="career-comparison-grid">'+rows.slice(3).map(card).join('')+'</div></details>':'')+(reviewed.length?'<details class="more-info"><summary>My profession comparisons</summary><ul>'+reviewed.map(r=>'<li><a href="'+url(r.id,r.complete?'summary':0)+'">'+h(careerTitle(occupationById(r.id)))+'</a> · '+(r.complete?'questions reviewed':'in progress')+'</li>').join('')+'</ul></details>':'')+'</section>';
}
export function careerCheckPage(s,id,step='0'){
 const spec=careerCheckSpec(id,{legacy:!!s._historicalMatchRules,coreVersion:s._coreWorkVersion});if(!spec)return '<h1>Choose a profession to compare</h1><a href="#/journey/professions">Back to matches →</a>';
 if(step==='summary'){
  const complete=careerCheckComplete(s,id),direct=directMatchCandidates(s).some(r=>r.id===id&&(s._historicalMatchRules||r.confirmation.confirmed)),top=planMatchCandidates(s).top.some(r=>r.id===id),why=careerCheckReadiness(s,id);
  return '<section class="career-check"><p class="eyebrow">PROFESSION COMPARISON</p><h1>'+h(careerTitle(spec.o))+'</h1><h2>'+(top?'This is now among your Top matches.':direct?'Your answers support this profession.':complete?'Keep exploring before choosing.':'There are questions left to explore.')+'</h2><aside class="match-note"><h3>'+h(why.headline)+'</h3><p>'+h(why.detail)+'</p><a href="'+url(id,why.nextIndex)+'">'+h(why.nextLabel)+' →</a></aside><p>Considering a training route is separate from applying or choosing a career. Your earlier fields and answers stay available.</p><div class="guide-actions"><a class="button" href="#/journey/professions">See all my matches →</a><a class="button secondary" href="'+url(id)+'">Review these answers</a></div>'+(!direct?'<button class="text-link" data-action="journey-family" data-id="'+h(spec.family)+'">Explore more work in this field →</button>':'')+'</section>';
 }
 const index=Math.max(0,Math.min(spec.questions.length-1,Number(step)||0)),q=spec.questions[index],answers=q.kind==='core-work'?[s.profileJourney?.coreWork?.[q.id]?.response].filter(Boolean):s.profileJourney?.depth?.[spec.family]?.[q.id]||[],feedback=q.kind==='core-work'?s.profileJourney?.coreWork?.[q.id]?.response:s.profileJourney?.careerQuestionFeedback?.[q.id],feedbackLabels={unfamiliar:'This work is unfamiliar to me','not-interested':'These activities do not interest me',unsure:'Unsure / skip'};
 const feedbackButton=(value,label)=>'<button class="text-link" data-action="career-check-'+value+'" data-career="'+h(id)+'" data-question="'+h(q.id)+'">'+label+'</button>';
 return '<section class="career-check"><div class="question-toolbar"><a href="'+(index?'#/journey/check-career/'+h(id)+'/'+(index-1):'#/journey/professions')+'">← Back</a><a href="#/overview">Save & pause</a></div><p class="eyebrow">'+(explorationExample(q.id)?'EXPLORE AN INTEREST':'COMPARE '+h(careerTitle(spec.o).toUpperCase()))+'</p><p>Question '+(index+1)+' of '+spec.questions.length+'</p>'+explorationExample(q.id)+'<h1>'+h(s.modelFollowUpQuestions?.[q.id]||q.prompt)+'</h1>'+(s.modelFollowUpQuestions?.[q.id]?'<details class="more-info"><summary>Original occupational activity</summary><p>'+h(q.activity)+'</p><p>This plain-language follow-up asks about interest in learning the work. It does not require prior professional experience.</p></details>':'')+(q.kind==='core-work'&&s.profileJourney?.coreWork?.[q.id]?.source==='profile-inferred'?'<p class="match-note">This suggested answer was inferred from the example’s profile ('+h(s.profileJourney.coreWork[q.id].confidence)+' confidence). Select Yes or No to confirm a direct response in this preview.</p>':'')+(q.kind==='core-work'&&q.editorialPrompt?'<p class="match-note">Think about whether you would like to learn this work. You do not need to know its professional tools already.</p>'+((coreWorkBank[id]?.optionalContext||[]).length?'<details class="more-info"><summary>Skills and special duties on this route</summary><ul>'+coreWorkBank[id].optionalContext.map(t=>'<li>'+h(t)+'</li>').join('')+'</ul><p>Training and role requirements still apply when you pursue this route.</p></details>':''):'')+(q.source?'<p><a href="'+h(q.source)+'" target="_blank" rel="noopener">Read the occupational task source ↗</a></p>':'')+'<p>For a specific work activity, choose Yes or No. For the earlier comparison questions, choose any parts you would like to try. If none fits, tell us whether the work is unfamiliar or does not interest you.</p><div class="profile-answer-grid">'+q.options.map(o=>'<button class="button secondary" data-action="career-check-toggle" data-career="'+h(id)+'" data-question="'+h(q.id)+'" data-id="'+h(o.id)+'" aria-pressed="'+answers.includes(o.id)+'">'+h(o.text)+'</button>').join('')+'</div>'+(['unfamiliar','not-interested','unsure'].includes(feedback)?'<p role="status">Your earlier response: '+h(feedbackLabels[feedback])+'. You can change it here.</p>':'')+'<p class="match-note">Earlier answers are shown when you have seen this question before. An edit also updates comparisons that use the same question.</p><div class="guide-actions"><button class="button" data-action="career-check-next" data-career="'+h(id)+'" data-question="'+h(q.id)+'">'+(index===spec.questions.length-1?'See my comparison →':'Next →')+'</button>'+feedbackButton('unfamiliar','This work is unfamiliar to me')+feedbackButton('not-interested','These activities do not interest me')+feedbackButton('skip','Unsure / skip this question')+'</div><p>Unfamiliar work stays open for exploration. These follow-ups do not change your official interest answers.</p></section>';
}

export function pendingProfessionPanel(s){const rows=planMatchCandidates(s).needsConfirmation||[];if(!rows.length)return '';return '<section class="career-comparisons"><h2>Needs confirmation</h2><p>These options share interests or tasks you liked. Confirm the defining work before treating them as Top matches. Unfamiliar work stays open.</p><ul>'+rows.map(r=>{const why=careerCheckReadiness(s,r.id,{includeRanking:false});return '<li><strong>'+h(careerTitle(r.o))+'</strong> · '+h(r.confirmation.headline)+'<p>'+h(r.confirmation.detail)+(r.interestContrast?' Your wider interests point elsewhere; try this work before choosing.':'')+'</p><a href="'+url(r.id,why.nextIndex)+'">Compare the defining work →</a></li>';}).join('')+'</ul></section>';}
